const button=document.querySelector('.menu');const nav=document.querySelector('.nav');if(button&&nav)button.addEventListener('click',()=>nav.classList.toggle('open'));

// Feed data is generated by an authorized server-side social connector.
// GitHub Pages cannot securely hold Meta API access tokens, so the website
// fetches a pre-published JSON feed. Never place social access tokens here.
(async function renderConnectedSocialPosts() {
  const container = document.getElementById('live-social-feed');
  if (!container) return;
  try {
    const response = await fetch('assets/social-feed.json', {cache:'no-store'});
    if (!response.ok) return;
    const data = await response.json();
    const posts = Array.isArray(data.posts) ? data.posts : [];
    if (!posts.length) return;
    container.textContent = '';
    for (const item of posts.slice(0,9)) {
      if (!item || !/^https:\/\//.test(item.url||'') || !/^https:\/\//.test(item.image||'')) continue;
      const card = document.createElement('a');
      card.className='social-post';card.href=item.url;
      card.target='_blank';card.rel='noopener noreferrer';
      const pic=document.createElement('img');pic.src=item.image;
      pic.alt=item.alt||'Recent Hero Headquarters social post';pic.loading='lazy';
      const body=document.createElement('div');body.className='social-post-body';
      const platform=document.createElement('span');platform.className='social-post-source';
      platform.textContent=item.platform==='instagram'?'Instagram':'Facebook';
      const caption=document.createElement('p');caption.textContent=item.caption||'';
      const time=document.createElement('time');time.textContent=item.date||'';
      body.append(platform,caption,time);card.append(pic,body);container.append(card);
    }
  } catch (err) { /* Keep explicit connection state instead of an empty widget */ }
})();
